//! U0 (plans/research/UTILITY-CSS.md): the types of the utility-class table, [`crate::utilities`],
//! generated by `tools/metadata/style/gen_utilities.py` from `metadata/style/utilities.yaml` (the
//! hand-written Tailwind names), `metadata/style/tailwind-v4.yaml` (the names we don't render) and
//! `metadata/semantics/egui.json` (the egui style table, states, parts and theme tokens).
//!
//! Data only: U1's resolver parses a class against it (namespace by longest name, value by source)
//! and emits the rule; U4's checker reads the same table. Values are the theme's tokens
//! (`var(--sv-<token>)`): scales resolve their patterns against the active theme, so an app's own
//! tokens (`--sv-cad-panel`) are values too; `defaults` are the built-in theme's, for docs,
//! completions and "did you mean".

/// The engine settings of the vocabulary.
#[derive(Clone, Copy, Debug)]
pub struct Config {
    /// The author-origin cascade layer utilities go in, below unlayered component rules (UQ3).
    pub layer: &'static str,
    /// Off unless the embed turns it on (UQ8).
    pub opt_in: bool,
    /// The embed may set a prefix (`tw`): then only `tw:`-prefixed classes are utilities (UQ8).
    pub prefix_optional: bool,
    /// Every token value is `var(<token_prefix><token>)`.
    pub token_prefix: &'static str,
    /// The severity of a colour literal in `[...]` (UQ6): by default, and under the strict profile.
    pub arbitrary_color: (&'static str, &'static str),
}

/// One token pattern of a [`Scale`].
#[derive(Clone, Copy, Debug)]
pub struct TokenPattern {
    /// With one `*`, the value name is what `*` matches (`space-*`: `space-7` is `7`); without, the
    /// exact token, named by `name`.
    pub glob: &'static str,
    /// The value name of an exact token; `Some("")` is the bare utility (`rounded`).
    pub name: Option<&'static str>,
}

/// A token family: the values of `p-*` (space), `text-*` (font-size), `bg-*` (colors).
#[derive(Clone, Copy, Debug)]
pub struct Scale {
    pub name: &'static str,
    /// The type of its tokens in the theme manifest (`length`, `color`, `shadow`, `duration`,
    /// `easing`, `font-family`). With no patterns, the scale is every token of this type (colours).
    pub token_type: &'static str,
    pub patterns: &'static [TokenPattern],
    /// Token globs left out (`font-*` without `font-size*`).
    pub exclude: &'static [&'static str],
    /// The built-in theme's (value name, token), in name order.
    pub defaults: &'static [(&'static str, &'static str)],
}

/// Where a namespace's values come from.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ValueSource {
    /// A [`Scale`] by name: `var(--sv-<token>)`.
    Scale(&'static str),
    /// `a/b`: a percentage.
    Fraction,
    /// An integer: that many px (`border-2`).
    IntPx,
    /// A non-negative number, as is (`grow-2`).
    Number,
    /// An integer 0 to 100, divided by 100 (`opacity-40`).
    Percent,
    /// An integer `n` substituted for `{n}` in the template (`grid-cols-3`).
    Integer(&'static str),
    /// `[value]`, checked against the property's type and range.
    Arbitrary,
}

/// A named value of a namespace: one CSS value per property of the row.
#[derive(Clone, Copy, Debug)]
pub struct Keyword {
    pub name: &'static str,
    pub values: &'static [&'static str],
}

/// What a [`Row`] generates.
#[derive(Clone, Copy, Debug)]
pub enum RowKind {
    /// `<name>-<value>` (and `<name>` for a scale value named `""`).
    Namespace {
        props: &'static [&'static str],
        values: &'static [ValueSource],
        keywords: &'static [Keyword],
        /// `-<name>-<value>` negates it.
        negative: bool,
    },
    /// The utility `<name>` with fixed declarations.
    Fixed { decls: &'static [(&'static str, &'static str)] },
}

/// One vocabulary row. A namespace can have several rows (`text-` is a colour, a size, an alignment):
/// their names are disjoint (the generator checks it for the built-in theme).
#[derive(Clone, Copy, Debug)]
pub struct Row {
    pub name: &'static str,
    /// The canonical order inside the utility layer (shorthands first: `p` < `px` < `pt`).
    pub rank: u16,
    /// The docs family (`spacing`, `color`, ...).
    pub family: &'static str,
    /// The engine item this row waits for (UTILITY-CSS §5, `E5`).
    pub requires: Option<&'static str>,
    /// Its properties aren't in the egui table yet: not a utility until they are.
    pub pending: bool,
    pub kind: RowKind,
}

/// A state variant: `hover:` is `&:hover`.
#[derive(Clone, Copy, Debug)]
pub struct StateVariant {
    pub name: &'static str,
    /// The built-in state it reads.
    pub state: Option<&'static str>,
    /// It matches when the state is off (`enabled`).
    pub negated: bool,
}

/// A prefix over the state variants: `not-hover:`; `{state}` in the selector is the state.
#[derive(Clone, Copy, Debug)]
pub struct CompoundVariant {
    pub name: &'static str,
    pub selector: &'static str,
    pub requires: Option<&'static str>,
}

/// A media variant (hoisted outside the rule).
#[derive(Clone, Copy, Debug)]
pub struct MediaVariant {
    pub name: &'static str,
    pub query: &'static str,
    pub requires: Option<&'static str>,
    /// A feature the engine doesn't evaluate yet.
    pub pending: bool,
}

/// Size variants from a scale (breakpoints `sm:`, containers `@sm:`), ascending.
#[derive(Clone, Copy, Debug)]
pub struct SizedVariants {
    pub scale: &'static str,
    /// The query of `<size>:`, `{px}` the size.
    pub min: &'static str,
    /// The query of `<max_prefix><size>:`.
    pub max: &'static str,
    pub max_prefix: &'static str,
    pub requires: Option<&'static str>,
    /// (name, px) of the built-in theme.
    pub sizes: &'static [(&'static str, f32)],
}

/// Per element tag: what its kind can match.
#[derive(Clone, Copy, Debug)]
pub struct KindStyle {
    pub tag: &'static str,
    /// The state variants it can match (built-in states, by pseudo-class name).
    pub states: &'static [&'static str],
    /// Its parts: (name, node part); `part-<name>:`.
    pub parts: &'static [(&'static str, bool)],
    /// The provider states it sets (`sv.overflow-top`).
    pub provider_states: &'static [&'static str],
}

/// A Tailwind v4 name we don't render, for `utility_unsupported`.
#[derive(Clone, Copy, Debug)]
pub struct Unsupported {
    /// A utility prefix (`ring` covers `ring-2`) or a variant name.
    pub name: &'static str,
    pub reason: &'static str,
    /// The replacement fix-it.
    pub replacement: Option<&'static str>,
    /// Utilities of ours that start with the name (a role named like it: `text-shadow-color`).
    pub allow: &'static [&'static str],
}

#[cfg(test)]
mod tests {
    use crate::tables::EGUI;
    use crate::utilities::*;
    use crate::utility_table::*;

    /// The generated rows name the egui table's properties (pending rows excepted), enum keywords
    /// are the property's values, and scale references resolve.
    #[test]
    fn rows_agree_with_the_egui_table() {
        for r in ROWS {
            let props: Vec<&str> = match r.kind {
                RowKind::Namespace { props, .. } => props.to_vec(),
                RowKind::Fixed { decls } => decls.iter().map(|d| d.0).collect(),
            };
            if !r.pending {
                for p in &props {
                    assert!(EGUI.get(p).is_some(), "{}: {p} is not an egui property", r.name);
                }
            }
            if let RowKind::Namespace { props, values, keywords, .. } = r.kind {
                for v in values {
                    if let ValueSource::Scale(s) = v {
                        assert!(SCALES.iter().any(|x| x.name == *s), "{}: scale {s}", r.name);
                    }
                }
                for k in keywords {
                    assert_eq!(k.values.len(), props.len(), "{}-{}", r.name, k.name);
                    for (p, v) in props.iter().zip(k.values) {
                        if let Some(prop) = EGUI.get(p).filter(|p| p.ty == crate::ValueType::Enum) {
                            assert!(prop.values.contains(v), "{}-{}: {v} is not a {p} keyword", r.name, k.name);
                        }
                    }
                }
            }
        }
        assert!(ROWS.windows(2).all(|w| w[0].rank < w[1].rank), "rows are in rank order");
        assert!(BREAKPOINTS.sizes.windows(2).all(|w| w[0].1 < w[1].1), "breakpoints ascend");
        assert!(KINDS.iter().any(|k| k.tag == "checkbox" && k.parts.iter().any(|p| p.0 == "indicator")));
    }
}
